entries[89894] = { ["name"] = "Shattered Glaive", ["text"] = "2 sec cast 5\nThis is a fragment of a large, three-bladed projectile fired from elven siege weapons. While glaive throwers are common even today, this fragment is of an ancient design with detailed ornamentation, even by night elf standards.\nShattered Glaive\nBinds when picked up" }
entries[89895] = { ["name"] = "Twisted Ammonite Shell", ["text"] = "2 sec cast 5\nAmmonites are an extinct type of shelled squid. The shell could be long like a spear or coiled in a variety of different ways. While this fossil is of a small specimen, they could grow quite large.\nTwisted Ammonite Shell\nBinds when picked up" }
