entries[90411] = { ["name"] = "Bodacious Door Knocker", ["text"] = "2 sec cast 5\nYou can only imagine what type of residence or business this artifact once adorned. This, er... knocker is in the shape of a buxom female dwarf with a gap-toothed smile, cheerfully bearing multiple pints.\nBodacious Door Knocker\nBinds when picked up" }
entries[90412] = { ["name"] = "Boot Heel with Scrollwork", ["text"] = "2 sec cast 5\nThe attention to detail in this simple boot heel suggests that the original piece of footwear might have been magical. The ornamentation is largely abstract, but you can make out small woodland animals- squirrels, deer, perhaps a skunk - hidden within all the scrollwork and stylized knots.\nBoot Heel with Scrollwork\nBinds when picked up" }
entries[90413] = { ["name"] = "Golden Chamber Pot", ["text"] = "2 sec cast 5\nApparently the rich and famous do all of their business in style. This piece is decorated with leaping fish and a running stream.\nGolden Chamber Pot\nBinds when picked up" }
entries[90414] = { ["name"] = "Despawn All Summons" }
entries[90415] = { ["name"] = "Winged Helm of Corehammer", ["text"] = "2 sec cast 5\nJudging from the size of this helm, Thane Corehammer of the Dark Irons must have been enormous, or possibly just enormously fat.\nWinged Helm of Corehammer\nBinds when picked up" }
entries[90416] = { ["name"] = "Eject Passenger All" }
entries[90417] = { ["name"] = "Poison Grain Supplies", ["text"] = "5 yd range\n1 sec cast\nPoison Grain Supplies in Blackrock Depths." }
entries[90418] = { ["name"] = "Volcanic Skybox" }
entries[90419] = { ["name"] = "Ironstar's Petrified Shield", ["text"] = "2 sec cast 5\nAccording to legend, Thane Ironstar of the Dark Iron dwarves carved this shield from a sacred high elven tree and then enchanted the item to turn it hard as stone.\nIronstar's Petrified Shield\nBinds when picked up" }
entries[90420] = { ["name"] = "Skull-Shaped Planter", ["text"] = "2 sec cast 5\nForest trolls have a strong affinity for plant life. The trolls' bodies themselves can support simple vegetation, such as moss or algae, which gives them their characteristic green color.\nSkull-Shaped Planter\nBinds when picked up" }
entries[90421] = { ["name"] = "Bracelet of Jade and Coins", ["text"] = "2 sec cast 5\nThis bracelet was made by connecting troll coins and polished bits of jade with a silver chain. Since trolls tend to prefer gold in their jewelry, it's possible the silver was captured from another race, which would make this piece of more recent origin. The coins are unusual and depict the leering faces of a series of lady trolls.\nBracelet of Jade and Coins\nBinds when picked up" }
entries[90422] = { ["name"] = "Colossal Cleave" }
entries[90423] = { ["name"] = "Gahz'rilla Figurine", ["text"] = "2 sec cast 5\nThe sand trolls summoned this huge, white hydra from a sacred pool within Zul'Farrak and then proceeded to worship it as a god. Gahz'rilla's scales are electrified, and even this small figurine seems alive with energy. Within Zul'Farrak, the legendary hydra is a common motif in architecture and ornamentation.\nGahz'rilla Figurine\nBinds when picked up" }
entries[90424] = { ["name"] = "Glubtok Transition Invisibility" }
entries[90425] = { ["name"] = "Rain of Fire", ["text"] = "Unlimited range\nInstant\nDeals Fire damage to enemies in the area of the blast" }
entries[90426] = { ["name"] = "Rain of Fire", ["text"] = "Unlimited range\nInstant\nShoots a fireball into the Crucible of Carnage." }
entries[90427] = { ["name"] = "Carried by Cromush" }
entries[90428] = { ["name"] = "Reverse Cast Ride" }
entries[90429] = { ["name"] = "Atal'ai Scepter", ["text"] = "2 sec cast 5\n'Atal'ai' means 'devoted ones' in Zandali, and this twisted group of trolls was devoted to the blood god, Hakkar: a being of extreme malevelonce who recently tasted defeat in Zul'Gurub, ancient capital of the Gurubashi empire. This scepter is decorated with a bat motif, possibly a connection to Hir'eek, the primal bat god.\nAtal'ai Scepter\nBinds when picked up" }
entries[90430] = { ["name"] = "Kill Credit" }
entries[90431] = { ["name"] = "See Quest Invis 7" }
entries[90432] = { ["name"] = "Devilsaur Tooth", ["text"] = "2 sec cast 5\nDevilsaurs are among the largest predators to ever walk Azeroth. While most died out long ago, some thrive in isolated pockets to this day. There is much speculation about the purpose of the devilsaur's degenerate front arms. One theory is that they help devilsaurs rise to a standing position; another theory suggests that the arms titillate females. More observation is necessary.\nDevilsaur Tooth\nBinds when picked up" }
entries[90433] = { ["name"] = "Insect in Amber", ["text"] = "2 sec cast 5\nAmber is petrified tree resin. One of the purposes of tree resin is to defend the tree from attacking insects, so very rare hunks of amber may contain preserved insects within.\nInsect in Amber\nBinds when picked up" }
