entries[90451] = { ["name"] = "Kaldorei Amphora", ["text"] = "2 sec cast 5\nThis slender vase with two looping handles was used to mix or store Darnassian wine. Even after all this time, you can still detect a faint scent of ginger from the dried residue at the bottom of this vessel.\nKaldorei Amphora\nBinds when picked up" }
entries[90452] = { ["name"] = "Ancient Shark Jaws", ["text"] = "2 sec cast 5\nSharks have no true bones, only cartilage. Because their feeding habits involve biting things with a great deal of force, losing teeth is common. Therefore, sharks have multiple rows of teeth which they replace constantly throughout their lifetimes.\nAncient Shark Jaws\nBinds when picked up" }
entries[90453] = { ["name"] = "Hairpin of Silver and Malachite", ["text"] = "2 sec cast 5\nEngraved beneath the setting for the precious stone are the words 'To Theleste, on her twenty-fourth birth year.'\nHairpin of Silver and Malachite\nBinds when picked up" }
entries[90454] = { ["name"] = "Item - Death Knight T11 Blood 2P Bonus", ["text"] = "Increases the damage done by your Death Strike ability by 5%." }
entries[90456] = { ["name"] = "Item - Death Knight T11 Blood 4P Bonus", ["text"] = "Increases the duration of your Icebound Fortitude ability by 50%." }
entries[90457] = { ["name"] = "Item - Death Knight T11 DPS 2P Bonus", ["text"] = "Increases the critical strike chance of your Death Coil and Frost Strike abilities by 5%." }
entries[90458] = { ["name"] = "Delicate Music Box", ["text"] = "2 sec cast 5\nThis box is of sandalwood with a tiny clockwork elf and nightsaber within. Although the winding mechanism is no longer functional, you can imagine the two would dance together while music played. Engraved on the bottom: 'To my dearest Theleste.'\nDelicate Music Box\nBinds when picked up" }
entries[90459] = { ["name"] = "Item - Death Knight T11 DPS 4P Bonus", ["text"] = "Each time you gain a Death Rune or trigger your Killing Machine talent, you also gain 1% increased attack power for 30 sec. Stacks up to 3 times." }
