entries[90473] = { ["name"] = "Item - Rogue T11 4P Bonus", ["text"] = "Each of your melee autoattacks has a 1% chance to activate Deadly Scheme for 15 sec, increasing the critical strike chance on your next Eviscerate or Envenom by 100%.\n(Proc chance: 1%)" }
