entries[90831] = { ["name"] = "Fiendish Whip", ["text"] = "2 sec cast 5\nWarlocks rose to prominence among the orcs as Gul'dan rose to power. This succubus whip is formed of the plaited flesh of several different creatures, some of them likely humanoid.\nFiendish Whip\nBinds when picked up" }
entries[90832] = { ["name"] = "Tile of Glazed Clay", ["text"] = "2 sec cast 5\nThere must have once been many of these tiles decorating the walls or floor of a Draenor fortress or stateroom. The tile depicts herd animals in a field of green and yellow glaze, much like Nagrand looks today. The border is a checkerboard of black and brown.\nTile of Glazed Clay\nBinds when picked up" }
entries[90833] = { ["name"] = "Skull Drinking Cup", ["text"] = "2 sec cast 5\nThis cup is fierce looking, but has the design flaw that liquid will keep dribbling out of the eye sockets. So thirsty....\nSkull Drinking Cup\nBinds when picked up" }
