entries[90860] = { ["name"] = "Carved Harp of Exotic Wood", ["text"] = "2 sec cast 5\nThis small harp was held in one hand, like a lyre. It has a deep wooden sounding box with seven strings knotted around a tuning bar. It is capable of playing music, but seems to only produce sad, melancholy notes.\nCarved Harp of Exotic Wood\nBinds when picked up" }
entries[90861] = { ["name"] = "Strange Silver Paperweight", ["text"] = "2 sec cast 5\nIf this object was not used as a draenei paperweight, then you have no idea of its function. It appears to be a blob of petrified mercury with one flat side so that it can sit on a desk.\nStrange Silver Paperweight\nBinds when picked up" }
entries[90864] = { ["name"] = "Scepter of the Nathrezim", ["text"] = "2 sec cast 5\nThe Nathrezim, also known as dreadlords, act as intelligence agents and interrogators of the Burning Legion. While they are powerful foes on the battlefield, they prefer to turn nations against each other through manipulation and guile.\nScepter of the Nathrezim\nBinds when picked up" }
