entries[90968] = { ["name"] = "Baroque Sword Scabbard", ["text"] = "2 sec cast 5\nThis sword sheath is almost distasteful in its ornamentation. Every bit of exposed surface has been carved, gilded or inscribed upon. It is likely the weapon this scabbard once carried was highly magical or ceremonial in nature.\nBaroque Sword Scabbard\nBinds when picked up" }
