entries[90978] = { ["name"] = "Energize!", ["text"] = "3 sec cast\nIncreases the caster's attack and casting speed by 50% and the damage it deals by 25%." }
entries[90980] = { ["name"] = "Cleave", ["text"] = "Melee Range\nNext Melee\nInflicts 150% of normal melee damage to an enemy and its nearest allies, affecting up to 3 targets." }
entries[90983] = { ["name"] = "Arrival of the Naaru", ["text"] = "2 sec cast 15\nThis crystal seems to be a magical recording device of some sort. The message it plays is in a language you can't entirely decipher, but you gather it is either a recording or a recreation of the first meeting of the eredar and the naaru.\nArrival of the Naaru\nBinds when picked up\nToy\nUse: Witness a recording of the arrival of the naaru. (3 Min Cooldown)" }
entries[90984] = { ["name"] = "The Last Relic of Argus", ["text"] = "2 sec cast 15\nBefore they lived on Azeroth or Draenor, the draenei, who still called themselves the eredar at the time, lived on Argus. When Sargeras took notice of Argus, Prophet Velen fled with some of his people, who became the draenei. The remaining eredar were absorbed into the Burning Legion. This simple crystal was taken from Argus when Velen fled. The inscription on the bottom reads, 'I long for Mac'Aree.'\nThe Last Relic of Argus\nBinds when picked up\nUse: Teleports you exactly where you want to go... if you aren't too picky. (12 Hrs Cooldown)\n\"One of the few things the draenei were able to take with them on their flight from Argus.\"" }
entries[90985] = { ["name"] = "Dead Winds", ["text"] = "Instant\nSpell Power increased by 6 for 15 sec." }
entries[90986] = { ["name"] = "Item - Proc Stacking Spell Power", ["text"] = "Your healing and damage periodic spells grant 6 spell power each time they heal or deal damage. Lasts 15 sec, stacking up to 20 times.\n(500ms cooldown)" }
entries[90987] = { ["name"] = "Plated Elekk Goad", ["text"] = "2 sec cast 5\nElekk are mammoth-like creatures native to Draenor, particularly the Nagrand area. The draenei domesticated elekk for use as mounts. This goad is a long pointed stick used for motivating surly elekk that haven't completed their training.\nPlated Elekk Goad\nBinds when picked up" }
entries[90988] = { ["name"] = "Intricate Treasure Chest Key", ["text"] = "2 sec cast 5\nWhile vrykul technology in general is slightly behind that of the Horde or Alliance, the detail of the design on this simple key is astounding. In vrykul culture, it is the woman of the household who keeps all the keys, often displaying them prominently to show her status. 'Does not open Dark Cleric Salem's chest.'\nIntricate Treasure Chest Key\nBinds when picked up" }
entries[90989] = { ["name"] = "Hymn of Power", ["text"] = "Instant\nSpell Power increased by 606 for 10 sec." }
entries[90990] = { ["name"] = "Item - Proc Spell Power", ["text"] = "Your spells have a chance to grant 606 spell power for 10 sec.\n(Proc chance: 10%, 50s cooldown)" }
