entries[90996] = { ["name"] = "Crescendo of Suffering", ["text"] = "Instant\nSpell Power increased by 606 for 10 sec." }
entries[90997] = { ["name"] = "Nifflevar Bearded Axe", ["text"] = "2 sec cast 15\nMany of the axes forged by the vrykul display an unusual style: the bottom edge of the axe blade extends down below the width of the butt. This style increases cutting area while minimizing weight; it can be used on both weapon and tools. Some dwarven axes show a similar construction.\nNifflevar Bearded Axe\nBinds to account\nOne-Hand Axe\n540 - 1,004 Damage Speed 2.60\n(296.92 damage per second)\n+36 Agility\n+87 Stamina\n+ 24 Hit\n+ 37 Critical Strike\nDurability 105 / 105\n71" }
entries[90998] = { ["name"] = "Song of Sorrow", ["text"] = "Your spells that damage a target below 35% health grant 606 spell power for 10 sec. Cannot activate again for 10 sec after bonus expires.\n(20s cooldown)" }
