entries[91008] = { ["name"] = "Scramseax", ["text"] = "2 sec cast 5\nScramseax are large, straight knives with a single edge and a simple hilt worn by many vrykul warriors as a sidearm. One common fighting style among warriors involves an axe in the main hand and the scramseax in the offhand.\nScramseax\nBinds when picked up" }
entries[91009] = { ["name"] = "Renegade Strength", ["text"] = "Instant\nFills the target with the strength of the Defias. Increases Physical damage done by 200%, Reduces damage taken from area of effect spells and abilities by 90%, and increases health by 300%." }
