entries[91188] = { ["name"] = "Infested Ruby Ring", ["text"] = "2 sec cast 5\nWhile beautiful, this ring is also disturbing. Within the huge, sharp ruby you can see a multitude of tiny creatures, spiders or mites perhaps, struggling to break free from their red prison.\nInfested Ruby Ring\nBinds when picked up" }
