entries[91191] = { ["name"] = "Gruesome Heart Box", ["text"] = "2 sec cast 5\nThis ornate box is covered with webs of gold and the skittering script of the nerubians. Inside is a heart, gray with age but still very much alive. It beats slowly, as if dormant.\nGruesome Heart Box\nBinds when picked up" }
